 null;yield return new WaitForSeconds(.3f);Bind();yield return WorldSession.Instance.RequestTransition("Office",p.transform);yield return new WaitForSeconds(.3f);Check(WorldSession.Instance.InOffice,"Office mantém transição aditiva existente");var filmPlayer=InteractionFocus.PlayerFor(m);filmPlayer.BlockControls(false);var filmTerminal=Object.FindObjectsByType<ComputerInteraction>(FindObjectsSortMode.None).First(x=>x.gameObject.scene.name=="Office");filmTerminal.EnterComputer();yield return new WaitForSeconds(2);filmTerminal.Operations.Show("Financeiro");yield return GridShiftV19Film.Record("18-office-financeiro-final",Camera.main,5);filmTerminal.ExitComputer();yield return new WaitForSeconds(1);var officePlayer=Object.FindObjectsByType<PlayerMovement>(FindObjectsSortMode.None).First(x=>x.gameObject.scene.name=="Office");yield return WorldSession.Instance.RequestTransition("SampleScene",officePlayer.transform);Check(!WorldSession.Instance.InInterior&&m==DeliveryManager.Instance,"Office retorna sem duplicar gerenciador");Check(Object.FindObjectsByType<AudioListener>(FindObjectsSortMode.None).Count(x=>x.isActiveAndEnabled)==1,"áudio mantém um listener após todas transições");Finish(true);
