 IEnumerator RearAccessChecks(){Place(p,van.CargoPosition-van.transform.forward*1.2f);Check(van.ToggleCargo(p),"abrir compartimento para testar acesso real");yield return new WaitForSeconds(.8f);foreach(float side in new[]{-.6f,0,.6f}){Aim(van.CargoAction.FocusCollider.bounds.center+van.transform.right*side);yield return null;Check(InteractionFocus.Selected(van.CargoAction,p.transform),"abertura reconhece mira ampla x="+side);}float capacity=van.capacityKg;van.capacityKg=1;Check(van.CargoCaption(p)=="Compartimento cheio"&&!van.TransferCargo(p)&&string.IsNullOrEmpty(van.CargoOrderId),"capacidade insuficiente rejeita carga sem perder caixa");van.capacityKg=capacity;var identity=m.GetComponent<GridShiftPersonalDelivery>().PackageIdentity;string id=identity.orderId;identity.orderId="outro-pedido";Check(!van.TransferCargo(p),"caixa com identidade diferente não é armazenada");identity.orderId=id;var wall=GameObject.CreatePrimitive(PrimitiveType.Cube);wall.name="Occlusion test fixture";wall.transform.SetPositionAndRotation(van.CargoPosition-van.transform.forward*.4f+Vector3.up*1.2f,van.transform.rotation);wall.transform.localScale=new Vector3(3,3,.1f);Physics.SyncTransforms();Aim(van.CargoAction.FocusCollider.bounds.center);yield return null;Check(!InteractionFocus.Selected(van.CargoAction,p.transform)&&!van.TransferCargo(p),"parede real bloqueia mira e transferência");Object.Destroy(wall);yield return null;Place(p,van.CargoPosition-van.transform.forward*4);Aim(van.CargoAction.FocusCollider.bounds.center);yield return null;Check(!InteractionFocus.Selected(van.CargoAction,p.transform)&&!van.TransferCargo(p),"interação continua limitada à proximidade real");Place(p,van.CargoPosition-van.transform.forward*1.2f);Check(van.ToggleCargo(p),"fechar após verificação preserva caixa em mãos");yield return new WaitForSeconds(.8f);}
 void Aim(Vector3 at){for(int i=0;i<3;i++){var horizontal=Vector3.ProjectOnPlane(at-p.CameraTransform.position,Vector3.up);if(horizontal.sqrMagnitude>.01f)p.transform.rotation=Quaternion.LookRotation(horizontal);}p.CameraTransform.LookAt(at);}
 IEnumerator StandAtEntrance(Vector3 access){var direction=Vector3.ProjectOnPlane(van.transform.position-access,Vector3.up).normalized;if(direction.sqrMagnitude<.1f)direction=Vector3.forward;for(int k=0;k<8;k++){var candidate=access+Quaternion.AngleAxis(k*45,Vector3.up)*direction*1.3f;if(!Physics.Raycast(candidate+Vector3.up,Vector3.down,out var floor,2.5f,~((1<<6)|(1<<7)|(1<<8)|(1<<9)),QueryTriggerInteraction.Ignore)||Mathf.Abs(floor.point.y-access.y)>.6f)continue;candidate.y=floor.point.y;Place(p,candidate);var cc=p.GetComponent<CharacterController>();float radius=cc.radius*p.transform.lossyScale.x,height=cc.height*p.transform.lossyScale.y;if(Physics.OverlapCapsule(p.transform.position+Vector3.up*(radius+.05f),p.transform.position+Vector3.up*(height-radius),radius,~0,QueryTriggerInteraction.Ignore).Any(c=>!c.transform.IsChildOf(p.transform)))continue;yield return new WaitForSeconds(.1f);Aim(access+Vector3.up*1.1f);yield return null;var target=Object.FindFirstObjectByType<GridShiftPackageInteraction>();if(target!=null&&InteractionFocus.Selected(target,p.transform)&&GridShiftDeliveryAccess.InReach(p,access))yield break;}Check(false,"entrada do cliente precisa de posição física visível e alcançável");}
 static void Capture(string name,Camera view,int width,int height){var overlays=Object.FindObjectsByType<Canvas>(FindObjectsSortMode.None).Where(c=>c.renderMode==RenderMode.ScreenSpaceOverlay).ToArray();var target=new RenderTexture(width,height,24);var previous=view.targetTexture;var active=RenderTexture.active;foreach(var c in overlays){c.renderMode=RenderMode.ScreenSpaceCamera;c.worldCamera=view;c.planeDistance=.8f;}view.targetTexture=target;Canvas.ForceUpdateCanvases();view.Render();RenderTexture.active=target;var image=new Texture2D(width,height,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,width,height),0,0);image.Apply();File.WriteAllBytes("Docs/Validacao19/"+name+".png",image.EncodeToPNG());view.targetTexture=previous;RenderTexture.active=active;foreach(var c in overlays){c.renderMode=RenderMode.ScreenSpaceOverlay;c.worldCamera=null;}target.Release();Object.Destroy(target);Object.Destroy(image);}
